			function doSave(){
				
				// 데이터 변경사항이 없을시 "변경된 데이터가 없습니다" 출력
				if (!util.Grid.isModified(app, "grdList", "MSG")) return false;
				
				// 그리드 내 컬럼 유효성 체크
				if (!util.validate(app, "grdList")) return false;
				
				// 저장 서브미션 호출
				util.Submit.send(app, "subSave", function(pbSuccess){
					if(pbSuccess){
						doList("save");
					}
				});
			}

