			/*
			 * "문자보내기" 버튼(btnAdd)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnAddClick(e){
			    var btnAdd = e.control;
			    
			    var ipbCallTo2 = app.lookup("ipbCallTo2");
			    if (ipbCallTo2.value == "") {
			        util.Msg.alert(app, "발신자 전화번호를 입력해주시기 바랍니다.");
			        return;
			    }
			    //if (ipbCallTo2.value.length != 12) {
			        //util.Msg.alert(app, "발신자 전화번호는 12자리 수여야 합니다.");
			        //return;
			    //}
			    
			    var txaSmsTxt2 = app.lookup("txaSmsTxt2");
			    if (txaSmsTxt2.value == null || txaSmsTxt2.value.trim() == "") {
			        util.Msg.alert(app, "메시지 내용을 입력해주시기 바랍니다.");
			        return;
			    }
			    
			    var dsReceiver = app.lookup("dsReceiver");
			    var dsReceiver2 = app.lookup("dsReceiver2");
			    
			    dsReceiver2.clear();
			    
			    var grd1 = app.lookup("grd1");
			    for (var i=0; i < dsReceiver.getRowCount(); i++) {
			        if (grd1.isCheckedRow(i)) {
			            //console.log("i", i);
			            dsReceiver2.addRowData(dsReceiver.getRowData(i));
			        }
			    }
			    
			    //console.log("dsReceiver2", dsReceiver2.getRowDataRanged());
			    
			    //return;
			    
			    var receiverCount = dsReceiver2.getRowCount();
			    if (receiverCount == 0) {
			        util.Msg.alert(app, "수신자가 없습니다.");
			        return;
			    }
			    
			    var count = 0;
			    
			    for (var i=0; i < dsReceiver2.getRowCount(); i++) {
			        var rowData = dsReceiver2.getRowData(i);
			        if (rowData["MBL_TELNO"].length < 2 || rowData["MBL_TELNO"].substring(0, 2) != "01" 
			            || !(rowData["MBL_TELNO"].length == 10 || rowData["MBL_TELNO"].length == 11)) {
			            count++;
			        }
			    }
			    
			    if (count > 0) {
			        util.Msg.alert(app, "전체 " + dsReceiver2.getRowCount() + "건 중에서\n" + count + "건은 번호가 01로 시작하지 않거나\n자리수가 맞지 않아서 제외됩니다.", null, function(){
			             afterCheck();
			         });
			    } else {
			        afterCheck();
			    }
			        
			}

			function afterCheck() {
			    
			    var dsReceiver = app.lookup("dsReceiver2");
			    
			    for (var i = dsReceiver.getRowCount() - 1; i >= 0; i--) {
			        
			        var rowData = dsReceiver.getRowData(i);
			        
			        if (rowData["MBL_TELNO"].length < 2 || rowData["MBL_TELNO"].substring(0, 2) != "01"
			            || !(rowData["MBL_TELNO"].length == 10 || rowData["MBL_TELNO"].length == 11)) {
			            dsReceiver.deleteRow(i);
			            //console.log("delete", i);
			        }
			    }
			    dsReceiver.commit();
			    
			    
			    var dmParam = app.lookup("dmParam");
			    var reserveYN = dmParam.getValue("reserveYN");
			    
			    var dtiReqDate2 = app.lookup("dtiReqDate2");
			    var cmbStrTime2 = app.lookup("cmbStrTime2");
			    var cmbStrMin2 = app.lookup("cmbStrMin2");
			    
			    if (reserveYN == "R") {
			        if (dtiReqDate2.value == null || dtiReqDate2.value == "") {
			            util.Msg.alert(app, "예약 전송 날짜를 선택해주시기 바랍니다.");
			            return;
			        }
			        if (cmbStrTime2.value == null || cmbStrTime2.value == "") {
			            util.Msg.alert(app, "예약 전송 시간을 선택해주시기 바랍니다.");
			            return;
			        }
			        if (cmbStrMin2.value == null || cmbStrMin2.value == "") {
			            util.Msg.alert(app, "예약 전송 분을 선택해주시기 바랍니다.");
			            return;
			        }
			        
			        var dt = new Date();
			        var year = dt.getFullYear();
			        var month = dt.getMonth() + 1;
			        var date = dt.getDate();
			        var hour = dt.getHours();  // 0-23
			        var minutes = dt.getMinutes();  // 0-59
			        
			        var dateStr = year + "" + (month < 10 ? "0" + month : month) + "" + (date < 10 ? "0" + date : date)
			                    + "" + (hour < 10 ? "0" + hour : hour) + "" + (minutes < 10 ? "0" + minutes : minutes);
			        
			        var reserveTime1 = dtiReqDate2.value + "" + cmbStrTime2.value + "" + cmbStrMin2.value;

			        //console.log("dateStr", dateStr);
			        //console.log("reserveTime1", reserveTime1.replace(/\-/g, ""));
			        
			        if (Number(reserveTime1.replace(/\-/g, "")) < Number(dateStr)) {
			            util.Msg.alert(app, "예약시간이 초과되었습니다.");
			            return;
			        }
			        
			        var reserveTime = dtiReqDate2.value + " " + cmbStrTime2.value + ":" + cmbStrMin2.value;
			        //console.log("reserveTime", reserveTime);
			        
			        dmParam.setValue("reserveTime", reserveTime);
			    }
			    
			    var grd1 = app.lookup("grd1");
			    
			    if(grd1.getCheckRowIndices().length == 0){
			        util.Msg.alert(app, "수신 리스트에서 대상자를 선택해주세요.");
			        false;
			    }else {
			        if (dsReceiver.getRowCount() > 0) {
			            
			            util.Submit.send(app, "subSend", function(pbSuccess) {
			                if (pbSuccess) {
			                    if (reserveYN == "R") {
			                        util.Msg.alert(app, "예약되었습니다.");
			                    } else {
			                        util.Msg.alert(app, "발송되었습니다.");
			                    }
			                    app.getHost().returnValue = "success";
			                }
			            });
			        }
			    }
			    
			}

