			function checkReserveTime() {
			    
			    var dtiReqDate2 = app.lookup("dtiReqDate2");
			    var cmbStrTime2 = app.lookup("cmbStrTime2");
			    var cmbStrMin2 = app.lookup("cmbStrMin2");
			    
			    //console.log("dtiReqDate2", dtiReqDate2.value);
			    
			    var dt = new Date();
			    var year = dt.getFullYear();
			    var month = dt.getMonth() + 1;
			    var date = dt.getDate();
			    var hour = dt.getHours();  // 0-23
			    var minutes = dt.getMinutes();  // 0-59
			    
			    var dateStr = year + "" + (month < 10 ? "0" + month : month) + "" + (date < 10 ? "0" + date : date);
			    
			    //console.log(dateStr);
			    //console.log(dtiReqDate2.value.replace(/\D/g, ''));
			    
			    if (dtiReqDate2.value != null && dtiReqDate2.value != "") {
			        if (Number(dtiReqDate2.value.replace(/\D/g, '')) < Number(dateStr)) {
			            //console.log("impossible.");
			            return false;
			        } else {
			            //console.log("possible.");
			        }
			        
			        if (cmbStrTime2.value != null && cmbStrTime2.value != "" && cmbStrMin2.value != null && cmbStrMin2.value != "") {
			            var d = Number(dtiReqDate2.value.replace(/\D/g, ''))
			            //if (hour == 0) {
			                //hour = 24;
			                //d = Number(dtiReqDate2.value.replace(/\D/g, '')) - 1;
			            //}
			            
			            if (d < Number(dateStr)) {
			                //console.log("impossible.");
			                return false;
			            } else if (d == Number(dateStr)) {
			                var h = Number(cmbStrTime2.value);
			                var m = Number(cmbStrMin2.value);
			                //console.log("h", h, "hour", hour);
			                //console.log("m", m, "minutes", minutes);
			                if (h < hour) {
			                    return false;
			                } else if (h == hour && m <= minutes) {
			                    return false;
			                }
			            }
			            
			        } else if (cmbStrTime2.value != null && cmbStrTime2.value != "") {
			            var d = Number(dtiReqDate2.value.replace(/\D/g, ''))
			            //if (hour == 0) {
			                //hour = 24;
			                //d = Number(dtiReqDate2.value.replace(/\D/g, '')) - 1;
			            //}
			            
			            if (d < Number(dateStr)) {
			                //console.log("impossible.");
			                return false;
			            } else if (d == Number(dateStr)) {
			                var h = Number(cmbStrTime2.value);
			                if (h < hour) {
			                    return false;
			                }
			            }
			        }
			        
			    }
			    
			    return true;
			}

